import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch57Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("xy6_en_086","xy10_en_104","xy7_en_073","sm7_en_143");
    static final PokemonFamily LEGACY=PokemonFamily.MEGA_EVOLUTION_LEGACY;
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static Set<PokemonFamily> family(PokemonFamily f){return f==LEGACY?Set.of(LEGACY,PokemonFamily.EX_LEGACY):f==PokemonFamily.MEGA_EVOLUTION_EX?Set.of(f,PokemonFamily.EX):Set.of(f);}
    static GeneratedRuleBatch28Test.Config config(String id,PokemonFamily own,PokemonFamily other){var c=new GeneratedRuleBatch28Test.Config();c.trainer=NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();c.ownFamilies=family(own);c.defenderFamilies=family(other);return c;}
    static ServerMatch aiGame(String id){var m=GeneratedRuleBatch28Test.fixture(config(id,LEGACY,LEGACY));if(id.equals(IDS.get(0)))m.discardHandCardsByEffect(A,A,List.of(DynamicPassiveModifierTest.hand(m,A,"energy").instanceId()));return m;}
    static CardInstance source(ServerMatch m,UUID p){return DynamicPassiveModifierTest.hand(m,p,"trainer");}
    public static void main(String[] args){metadata();turbo();catcher();checkup();knockouts();System.out.println("NonPokemonBatch57Test passed: all 94 legacy Mega metadata and both Primals, modern Mega ex excluded; discard basic Energy/valid own hosts, opponent Bench-only gust; two-sided Active/Bench checkup counters, repeated checkups, Stadium removal and simultaneous knockouts");}
    static void metadata(){var db=BundledRules.loadCardDefinitions();var megas=db.all().stream().filter(c->c.pokemonFamilies().contains(LEGACY)).toList();check(megas.size()==94&&megas.stream().allMatch(c->c.pokemonFamilies().contains(PokemonFamily.EX_LEGACY)&&!c.pokemonFamilies().contains(PokemonFamily.MEGA_EVOLUTION_EX)),"Legacy Mega metadata wrong");for(String id:List.of("xy1_en_002","xy5_en_055","xy5_en_086","xy10_en_118","xyalt_en_201"))check(db.find(id).orElseThrow().pokemonFamilies().contains(LEGACY),"Missing M/Primal identity");check(!db.find("me1_en_003").orElseThrow().pokemonFamilies().contains(LEGACY),"Modern Mega ex treated as legacy M");}
    static void turbo(){for(PokemonFamily f:List.of(LEGACY,PokemonFamily.EX_LEGACY,PokemonFamily.MEGA_EVOLUTION_EX,PokemonFamily.GX))for(boolean special:List.of(false,true)){
        var c=config(IDS.get(0),f,LEGACY);if(special)c.specialEnergy=EnergyProfile.fixed(EnergyType.COLORLESS,2);var m=GeneratedRuleBatch28Test.fixture(c);var energy=DynamicPassiveModifierTest.hand(m,A,"energy");m.discardHandCardsByEffect(A,A,List.of(energy.instanceId()));var source=source(m,A);boolean allowed=f==LEGACY&&!special;check(m.canPlayTrainer(A,source.instanceId(),null)==allowed,"Mega Turbo wrong family/energy eligibility");if(!allowed){GeneratedRuleBatch8Test.reject(()->m.playTrainer(A,source.instanceId(),null));continue;}
        m.playTrainer(A,source.instanceId(),null);var q=m.effectCardPrompt(A);check(q.candidates().equals(List.of(energy)),"Mega Turbo wrong discard selection");m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(energy.instanceId()));var p=m.effectAttachmentPrompt(A);UUID bench=m.benchPokemonView(A).getFirst().pokemonId();check(p.targets().contains(bench)&&p.targets().contains(m.activePokemonView(A).pokemonId())&&!p.targets().contains(m.activePokemonView(B).pokemonId()),"Mega Turbo wrong recipient scope");m.chooseEffectAttachmentTarget(A,p.resolutionId(),p.step(),bench);NonPokemonBatch2Test.settle(m);check(m.benchPokemonView(A).getFirst().attachedEnergyIds().contains(energy.instanceId())&&!m.energyAttached(A),"Mega Turbo failed effect attachment");
    }}
    static void catcher(){for(PokemonFamily f:List.of(LEGACY,PokemonFamily.EX_LEGACY,PokemonFamily.MEGA_EVOLUTION_EX,PokemonFamily.GX)){
        var m=GeneratedRuleBatch28Test.fixture(config(IDS.get(1),LEGACY,f));var source=source(m,A);check(m.canPlayTrainer(A,source.instanceId(),null)==(f==LEGACY),"Mega Catcher wrong family");if(f!=LEGACY)continue;UUID target=m.benchPokemonView(B).getFirst().pokemonId();m.playTrainer(A,source.instanceId(),null);var q=m.effectPokemonPrompt(A);check(q.targets().size()==1&&q.targets().getFirst().pokemonId().equals(target),"Mega Catcher allowed Active/own target");m.chooseEffectPokemon(A,q.resolutionId(),q.step(),target);NonPokemonBatch2Test.settle(m);check(m.activePokemonView(B).pokemonId().equals(target),"Mega Catcher did not switch selected Bench");
    }}
    static boolean affected(String id,PokemonFamily f){return id.equals(IDS.get(2))?f==LEGACY:Set.of(LEGACY,PokemonFamily.EX_LEGACY,PokemonFamily.GX).contains(f);}
    static void checkup(){for(String id:IDS.subList(2,4))for(PokemonFamily f:List.of(LEGACY,PokemonFamily.EX_LEGACY,PokemonFamily.GX,PokemonFamily.MEGA_EVOLUTION_EX,PokemonFamily.EX,PokemonFamily.V))for(UUID actor:List.of(A,B)){
        var m=GeneratedRuleBatch28Test.fixture(config(id,f,LEGACY));if(actor.equals(B))m.endTurn(A);m.playTrainer(actor,source(m,actor).instanceId(),null);check(m.activePokemonView(A).damage()==0&&m.activePokemonView(B).damage()==0,"Checkup Stadium damaged on play");
        for(int tick=1;tick<=2;tick++){m.endTurn(m.currentPlayer());NonPokemonBatch2Test.settle(m);int amount=id.equals(IDS.get(2))?20:10;check(m.activePokemonView(A).damage()==(affected(id,f)?amount*tick:0)&&m.benchPokemonView(A).getFirst().damage()==(affected(id,f)?amount*tick:0)&&m.activePokemonView(B).damage()==amount*tick&&m.benchPokemonView(B).getFirst().damage()==amount*tick,"Wrong two-sided family/checkup counter amounts");}
        int before=m.activePokemonView(B).damage();m.discardStadiumByEffect(m.currentPlayer());m.endTurn(m.currentPlayer());NonPokemonBatch2Test.settle(m);check(m.activePokemonView(B).damage()==before,"Departed Stadium kept dealing counters");
    }}
    static void knockouts(){for(String id:IDS.subList(2,4)){
        var m=GeneratedRuleBatch28Test.fixture(config(id,LEGACY,LEGACY));UUID own=m.activePokemonView(A).pokemonId(),other=m.activePokemonView(B).pokemonId();for(UUID p:List.of(A,B)){UUID host=m.activePokemonView(p).pokemonId();m.placeDamageCountersByEffect(A,p,host,60);m.placeDamageCountersByEffect(A,p,host,39);}int a=NonPokemonBatch51Test.prizes(m,A),b=NonPokemonBatch51Test.prizes(m,B);m.playTrainer(A,source(m,A).instanceId(),null);m.endTurn(A);NonPokemonBatch2Test.settle(m);check(!m.activePokemonView(A).pokemonId().equals(own)&&!m.activePokemonView(B).pokemonId().equals(other)&&NonPokemonBatch51Test.prizes(m,A)==a-1&&NonPokemonBatch51Test.prizes(m,B)==b-1,"Checkup did not settle both lethal counters/prizes");
    }}
}
